<?php
if (!isset($list, $monitoring)) { http_response_code(404); exit; }
?>
<?php if (!$list['rows']): ?>
<div class="empty-state"><h2><?= $list['search'] !== '' || $list['jenis'] !== '' ? 'Transaksi tidak ditemukan.' : 'Belum ada transaksi keuangan.' ?></h2><p><?= $monitoring ? 'Data yang dicatat Bendahara akan ditampilkan di sini.' : 'Catat pemasukan dan pengeluaran agar keuangan tersusun rapi.' ?></p>
<?php if (!$monitoring): ?><a class="button primary" href="<?= keuangan_escape(app_url('bendahara/keuangan/tambah.php')) ?>"><?= $list['search'] !== '' || $list['jenis'] !== '' ? 'Tambah Transaksi' : 'Tambah Transaksi Pertama' ?></a><?php endif; ?></div>
<?php else: ?>
<div class="table-responsive"><table><thead><tr><th>No</th><th>Tanggal</th><th>Jenis</th><th>Kategori</th><th>Keterangan</th><th>Jumlah</th><th><?= $monitoring ? 'Diinput Oleh' : 'Aksi' ?></th></tr></thead><tbody>
<?php foreach ($list['rows'] as $i => $row): $pendingId = (int) (($pendingDeleteMap ?? [])[(int) $row['id_keuangan']] ?? 0); ?>
<tr><td><?= $list['offset'] + $i + 1 ?></td><td class="nowrap"><?= keuangan_escape(date('d-m-Y', strtotime($row['tanggal']))) ?></td><td><span class="type-badge <?= $row['jenis'] === 'pemasukan' ? 'income' : 'expense' ?>"><?= $row['jenis'] === 'pemasukan' ? 'Pemasukan' : 'Pengeluaran' ?></span></td><td class="category"><?= keuangan_escape($row['kategori']) ?></td><td class="description"><?= keuangan_escape($row['keterangan'] ?: '—') ?></td><td class="amount"><?= keuangan_rupiah($row['jumlah']) ?></td><td><?php if ($monitoring): ?><?= keuangan_escape($row['creator'] ?? 'Data Lama') ?><?php if (isset($pendingDeleteMap[(int) $row['id_keuangan']])): ?> <span class="approval-badge pending">Menunggu Persetujuan Hapus</span><form method="POST" action="<?= keuangan_escape(app_url('admin/keuangan/approve_hapus.php')) ?>" class="inline-action"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int) $pendingDeleteMap[(int) $row['id_keuangan']] ?>"><button class="btn-small approve" type="submit">Setujui</button></form><form method="POST" action="<?= keuangan_escape(app_url('admin/keuangan/reject_hapus.php')) ?>" class="inline-action"><?= csrf_field() ?><input type="hidden" name="request_id" value="<?= (int) $pendingDeleteMap[(int) $row['id_keuangan']] ?>"><button class="btn-small reject" type="submit">Tolak</button></form><?php endif; ?><?php elseif ($pendingId): ?><span class="approval-badge pending">Menunggu Admin</span><?php else: ?><a class="edit-link" href="<?= keuangan_escape(app_url('bendahara/keuangan/edit.php') . '?id=' . (int)$row['id_keuangan']) ?>">Edit</a><form method="POST" action="<?= keuangan_escape(app_url('bendahara/keuangan/request_hapus.php')) ?>" class="inline-action" onsubmit="return confirm('Ajukan permintaan penghapusan data ini kepada Admin?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) $row['id_keuangan'] ?>"><button class="edit-link danger-link" type="submit">Ajukan Hapus</button></form><?php endif; ?></td></tr>
<?php endforeach; ?>
</tbody></table></div>
<?php endif; ?>
